import {
	assertNever,
	createModuleLogger,
	type SurfaceAppearanceDefinition,
	type SurfaceControlAppearance,
} from '@companion-surface/base'
import { DeviceModelId, type MXConsoleControlBounds, type MXConsoleModelInfo } from '@logitech-mx-creative-console/node'
import { getControlId } from './util.js'
// Generated by `yarn build:artwork`, so it is gitignored
// eslint-disable-next-line n/no-unpublished-import
import compiledArtworkJson from './artwork.generated.json' with { type: 'json' }

const logger = createModuleLogger('Appearance')

/**
 * The colour of the plastic on a graphite MX Creative Console.
 */
const BODY_COLOR = '#2b2b2b'

/**
 * Corner radius of a key, as a fraction of its shorter side.
 *
 * This is eyeballed rather than measured.
 */
const KEY_CORNER_RADIUS_RATIO = 0.12

/**
 * Space to add around a model's `faceSize`, in face units.
 *
 * A model's `faceSize` only covers the area its controls sit in, not the bezel around them, so
 * artwork which draws the whole device needs room to breathe.
 */
export interface FacePadding {
	left: number
	top: number
	right: number
	bottom: number
}

/**
 * Artwork compiled from `artwork/*.svg` by `tools/build-artwork.mjs`.
 */
interface CompiledArtwork {
	/** The artwork, as a base64 `data:` URI of an svg, whose viewBox is the padded face */
	bodyImage: string
	/** The `faceSize` the artwork was drawn around */
	faceSize: { width: number; height: number }
	/** Where the face sits within the artwork */
	padding: FacePadding
}

const COMPILED_ARTWORK: Record<string, CompiledArtwork | undefined> = compiledArtworkJson

/**
 * Which artwork each model is drawn with. Every model must be listed, so a new one can't be missed;
 * one which is `null` is drawn as its bare controls on a plain body.
 */
const MODEL_ARTWORK: Record<DeviceModelId, { artwork: string; bodyColor?: string } | null> = {
	[DeviceModelId.MX_CREATIVE_KEYPAD]: { artwork: 'mx-creative-keypad' },
	[DeviceModelId.MX_CREATIVE_DIALPAD]: { artwork: 'mx-creative-dialpad' },
}

function getModelArtwork(modelInfo: MXConsoleModelInfo): { artwork: CompiledArtwork | undefined; bodyColor: string } {
	const entry = MODEL_ARTWORK[modelInfo.id]
	const bodyColor = entry?.bodyColor ?? BODY_COLOR
	if (!entry) return { artwork: undefined, bodyColor }

	const artwork = COMPILED_ARTWORK[entry.artwork]
	if (!artwork) {
		logger.warn(`Missing artwork "${entry.artwork}" for ${modelInfo.id}`)
		return { artwork: undefined, bodyColor }
	}

	// Artwork drawn around a different face would put every control in the wrong place
	if (artwork.faceSize.width !== modelInfo.faceSize.width || artwork.faceSize.height !== modelInfo.faceSize.height) {
		logger.warn(
			`Artwork "${entry.artwork}" was drawn for a ${artwork.faceSize.width}x${artwork.faceSize.height} face, but ${modelInfo.id} is ${modelInfo.faceSize.width}x${modelInfo.faceSize.height}`,
		)
		return { artwork: undefined, bodyColor }
	}

	return { artwork, bodyColor }
}

/**
 * Describe how to draw the face of a model, from the bounds the library gives for each of its
 * controls.
 *
 * Keyed by the same control ids as `createSurfaceSchema`, and must cover every control that
 * produces, or the whole appearance is discarded by the host.
 */
export function createSurfaceAppearance(modelInfo: MXConsoleModelInfo): SurfaceAppearanceDefinition {
	const { artwork, bodyColor } = getModelArtwork(modelInfo)
	const padding = artwork?.padding

	const offsetX = padding?.left ?? 0
	const offsetY = padding?.top ?? 0

	const controls: Record<string, SurfaceControlAppearance> = {}

	for (const control of modelInfo.controls) {
		switch (control.type) {
			case 'button':
				controls[getControlId(control)] = {
					...translateBounds(control.bounds, offsetX, offsetY),
					kind: 'button',
					// The dialpad's buttons are round, while the keypad's are rounded squares
					shape:
						modelInfo.id === DeviceModelId.MX_CREATIVE_DIALPAD
							? { shape: 'ellipse' }
							: {
									shape: 'rect',
									cornerRadius: Math.min(control.bounds.width, control.bounds.height) * KEY_CORNER_RADIUS_RATIO,
								},
				}
				break
			case 'encoder':
				controls[getControlId(control)] = {
					...translateBounds(control.bounds, offsetX, offsetY),
					kind: 'encoder',
					// The small dial is a roller, so is wider than it is tall
					shape:
						control.bounds.width === control.bounds.height
							? { shape: 'ellipse' }
							: { shape: 'rect', cornerRadius: Math.min(control.bounds.width, control.bounds.height) / 2 },
				}
				break
			default:
				assertNever(control)
				break
		}
	}

	return {
		size: {
			width: modelInfo.faceSize.width + offsetX + (padding?.right ?? 0),
			height: modelInfo.faceSize.height + offsetY + (padding?.bottom ?? 0),
		},
		bodyColor,
		bodyImage: artwork?.bodyImage,
		controls,
	}
}

function translateBounds(
	bounds: MXConsoleControlBounds,
	offsetX: number,
	offsetY: number,
): Pick<SurfaceControlAppearance, 'x' | 'y' | 'width' | 'height'> {
	return {
		x: bounds.x + offsetX,
		y: bounds.y + offsetY,
		width: bounds.width,
		height: bounds.height,
	}
}
